-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Assembly - Weld consumables$q$, 23, 0),
    ($q$Assembly - Sealant and adhesive material$q$, 10, 0),
    ($q$Assembly - Pick and place$q$, 6, 1),
    ($q$Assembly - Mechanical assembly$q$, 4, 1),
    ($q$Assembly - Threaded insert$q$, 4, 1),
    ($q$Assembly - Lock bolt$q$, 5, 1),
    ($q$Assembly - Rivet$q$, 4, 1),
    ($q$Assembly - Manual MIG welding$q$, 15, 1),
    ($q$Assembly - Robotic MIG welding$q$, 19, 1),
    ($q$Assembly - Manual TIG welding$q$, 15, 1),
    ($q$Assembly - Robotic TIG welding$q$, 19, 1),
    ($q$Assembly - Manual spot welding$q$, 5, 1),
    ($q$Assembly - Robotic spot welding$q$, 8, 1),
    ($q$Assembly - Electron beam welding$q$, 13, 1),
    ($q$Assembly - Laser welding$q$, 12, 1),
    ($q$Assembly - Ultrasonic welding$q$, 5, 1),
    ($q$Assembly - Adhesive bonding$q$, 8, 1),
    ($q$Assembly - Fay sealing$q$, 4, 1),
    ($q$Assembly - Fillet sealing$q$, 4, 1),
    ($q$Assembly - Cap sealing$q$, 4, 1),
    ($q$Assembly - Weld prep$q$, 7, 1),
    ($q$Assembly - Weld clean up$q$, 4, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Assembly$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1078: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
